 async function goToStep(next:number){if(next>0&&!dimensionsReady){if(!inputDimensionsValid){setError('Nhập đủ chiều rộng và chiều dài thực tế từ 0,1 đến 100 m ở bước 1.');setStepUnsafe(0);return}if(!await applyMeasuredDimensions(Number(actualWidth),Number(actualLength)))return}setStepUnsafe(next)}
 useEffect(()=>{if(config.dimensions_source==='measured'){setActualWidth(String(config.roof_width_m));setActualLength(String(config.roof_height_m))}},[config.roof_width_m,config.roof_height_m,config.dimensions_source])
 const [health,setHealth]=useState<Health|null>(null),[backendError,setBackendError]=useState(false),[busy,setBusy]=useState<string|null>(null),[error,setError]=useState('')
